using System;using System.Reflection;using System.Xml;
class Program{static void Main(){var type=typeof(XmlReader).Assembly.GetType("System.Xml.LocalAppContextSwitches");var property=type.GetProperty("IsNetworkingEnabledByDefault",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);var cache=type.GetField("s_isNetworkingEnabledByDefault",BindingFlags.Static|BindingFlags.NonPublic);Console.WriteLine("DEFAULT:"+((bool)property.GetValue(null)?1:0)+","+cache.GetValue(null)+";");string line;while((line=Console.ReadLine())!=null){cache.SetValue(null,0);AppContext.SetSwitch("System.Xml.XmlResolver.IsNetworkingEnabledByDefault",true);AppContext.SetSwitch("TestSwitch.LocalAppContext.DisableCaching",false);foreach(char c in line){if(c=='n'||c=='N')AppContext.SetSwitch("System.Xml.XmlResolver.IsNetworkingEnabledByDefault",c=='N');else if(c=='d'||c=='D')AppContext.SetSwitch("TestSwitch.LocalAppContext.DisableCaching",c=='D');else if(c=='g')Console.Write(((bool)property.GetValue(null)?1:0)+","+cache.GetValue(null)+";");}Console.WriteLine();}}}
